<style>
:root{--purple:#7440c7;--purple-dark:#54259f;--purple-soft:#f6f1ff;--orange:#ff8a3d;--green:#e6f4e8;--ink:#161b42;--muted:#6d6b8d;--line:#ded9eb}
.ad-wizard,.ad-wizard *{box-sizing:border-box}.ad-wizard{display:grid;grid-template-columns:176px 1fr;grid-template-rows:92px 1fr 58px;width:min(1000px,calc(100vw - 32px));height:min(650px,calc(100vh - 32px));margin:auto;overflow:hidden;border:1px solid #e8e1f3;border-radius:12px;background:#fff;box-shadow:0 22px 55px #20233f2e;color:var(--ink);font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
.ad-sidebar{grid-row:1/4;padding:24px 20px;background:linear-gradient(#fbf8ff,#f5f0ff);border-right:1px solid #ded2f3}.ad-sidebar h3{margin:0;color:var(--purple-dark);font-size:18px}.ad-progress{margin-top:12px;font-size:11px}.ad-progress div{height:7px;margin-top:7px;border-radius:9px;background:#e1dbea}.ad-progress i{display:block;width:0;height:100%;border-radius:9px;background:var(--purple)}
.ad-wizard-steps{margin-top:25px}.ad-wizard-step{position:relative;display:flex;align-items:center;gap:10px;height:52px;font-size:11px;font-weight:600}.ad-wizard-step:not(:last-child):after{content:"";position:absolute;left:13px;top:39px;width:1px;height:26px;background:#d8cceb}.ad-wizard-step b{z-index:1;display:grid;place-items:center;width:27px;height:27px;border:1px solid #ccb9ee;border-radius:50%;background:#faf8ff;font-size:11px}.ad-wizard-step.active{font-weight:800}.ad-wizard-step.active b{border:1.5px solid var(--orange);background:#fff}
.ad-wizard-head{grid-column:2;display:flex;align-items:flex-start;justify-content:space-between;padding:22px 30px 10px;background:#fff}.ad-wizard-head h4{margin:0;font-size:25px;font-weight:800}.ad-wizard-head p{margin:6px 0 0;color:#66668b;font-size:11px}.ad-head-actions{display:flex;align-items:center;gap:20px}.ad-time{padding:7px 11px;border-radius:7px;background:var(--green);color:#266a36;font-size:11px}.ad-time:before{content:"◷";margin-right:7px;font-size:16px}.ad-wizard-close{width:28px;height:28px;padding:0;border:0;background:transparent;color:var(--ink);font-size:27px;line-height:1}
.ad-wizard-body{grid-column:2;min-height:0;padding:10px 30px 12px;overflow:auto}.ad-wizard-panel{display:none}.ad-wizard-panel.active{display:block}.ad-wizard-section{padding:16px;margin:0 0 12px;border:1px solid var(--line);border-radius:7px;background:#fff}.ad-wizard-section>h4{margin:0 0 13px;font-size:14px}.ad-profile{display:grid;grid-template-columns:130px 1fr;gap:22px;align-items:center}.ad-photo-box{display:flex;flex-direction:column;align-items:center}.ad-photo-preview{position:relative;display:grid;place-items:center;width:86px;height:86px;border:1.5px dashed #9570d5;border-radius:50%;background:#faf7ff;color:#8e68cb;font-size:0}.ad-photo-preview:before{content:"♙";font-size:43px}.ad-photo-preview:after{content:"●";position:absolute;right:-7px;bottom:4px;display:grid;place-items:center;width:31px;height:31px;border:1px solid var(--line);border-radius:50%;background:#fff;color:#62678b;font-size:11px;box-shadow:0 2px 7px #191c421f}.ad-photo-preview img{position:absolute;z-index:2;width:100%;height:100%;border-radius:50%;object-fit:cover}.ad-upload-copy{margin-top:8px;text-align:center}.ad-upload-copy label{cursor:pointer;font-size:11px;font-weight:600}.ad-upload-copy input{position:absolute;width:1px;height:1px;opacity:0}
.ad-wizard-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px 16px}.ad-wizard-grid.two,.ad-essential{grid-template-columns:repeat(2,minmax(0,1fr))}.ad-field label{display:block;margin-bottom:5px;font-size:10px;font-weight:700}.ad-field input,.ad-field select,.ad-field textarea{width:100%;height:38px;padding:7px 10px;border:1px solid #d5d2e3;border-radius:6px;background:#fff;color:#252849;font-size:11px}.ad-field textarea{height:60px;resize:vertical}.ad-field input:focus,.ad-field select:focus,.ad-field textarea:focus{border-color:#9b77d5;outline:0;box-shadow:0 0 0 3px #7440c719}.ad-field.full{grid-column:1/-1}.ad-required{color:#f04438}
.ad-optional{border:1px solid var(--line);border-radius:7px}.ad-optional summary{display:flex;align-items:center;min-height:52px;padding:0 16px;cursor:pointer;list-style:none}.ad-optional summary::-webkit-details-marker{display:none}.ad-info{display:grid;place-items:center;width:29px;height:29px;margin-right:11px;border-radius:50%;background:var(--green);color:#266a36;font-weight:900}.ad-optional-copy{display:flex;flex:1;flex-direction:column;gap:2px}.ad-optional-copy strong{font-size:11px}.ad-optional-copy small{color:#757397;font-size:9px}.ad-optional-fields{padding:13px 16px;border-top:1px solid #eeeaf4}.ad-document{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:10px;border:1px solid var(--line);border-radius:6px}.ad-document strong{display:block;font-size:11px}.ad-document small{color:var(--muted);font-size:9px}.ad-review{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.ad-review-card{padding:12px;border:1px solid var(--line);border-radius:7px}.ad-review-card h5{margin:0 0 6px;color:var(--purple-dark)}
.ad-wizard-error{display:none;margin:8px 0 0;padding:7px 9px;border-radius:5px;background:#fff0f0;color:#c9353b;font-size:10px}.ad-wizard-error.show{display:block}.ad-wizard-foot{grid-column:2;display:flex;align-items:center;gap:16px;padding:9px 30px;border-top:1px solid var(--line);background:#fff}.ad-required-note{margin-right:auto;color:#66668b;font-size:10px}.ad-wizard-status{color:#66668b;font-size:10px;white-space:nowrap}.ad-wizard-status strong{color:var(--ink)}.ad-foot-actions{display:flex;gap:10px}.ad-wizard-foot button{height:36px;padding:0 14px;border:1px solid #d7d2e4;border-radius:6px;background:#fff;color:#252849;font-size:10px;font-weight:700}.ad-wizard-foot .next,.ad-wizard-foot .save{border-color:var(--purple);background:var(--purple);color:#fff}.ad-wizard-foot .back{display:none}.ad-wizard-foot .back.visible{display:inline-block}
@media(max-width:760px){.ad-wizard{display:flex;width:100%;height:calc(100vh - 12px);flex-direction:column}.ad-sidebar{padding:12px 15px;border-right:0;border-bottom:1px solid #ded2f3}.ad-sidebar h3,.ad-progress{display:none}.ad-wizard-steps{display:grid;grid-template-columns:repeat(6,1fr);margin:0}.ad-wizard-step{justify-content:center;height:auto}.ad-wizard-step span,.ad-wizard-step:after{display:none}.ad-wizard-head,.ad-wizard-body,.ad-wizard-foot{padding-left:15px;padding-right:15px}.ad-time,.ad-photo-box,.ad-required-note{display:none}.ad-profile{grid-template-columns:1fr}.ad-wizard-grid,.ad-wizard-grid.two,.ad-essential{grid-template-columns:1fr}.ad-wizard-status{margin-right:auto}}
</style>
<div class="modal-content ad-wizard" id="ad-staff-wizard">
 <aside class="ad-sidebar"><h3>New Staff</h3><div class="ad-progress">Progress <strong id="ad-progress-percent">0%</strong><div><i id="ad-progress-bar"></i></div></div><nav class="ad-wizard-steps"><div class="ad-wizard-step active" data-wizard-step="0"><b>1</b><span>Basic Details</span></div><div class="ad-wizard-step" data-wizard-step="1"><b>2</b><span>Next of Kin</span></div><div class="ad-wizard-step" data-wizard-step="2"><b>3</b><span>Employment</span></div><div class="ad-wizard-step" data-wizard-step="3"><b>4</b><span>Documents</span></div><div class="ad-wizard-step" data-wizard-step="4"><b>5</b><span>System Access</span></div><div class="ad-wizard-step" data-wizard-step="5"><b>6</b><span>Review &amp; Save</span></div></nav></aside>
 <header class="modal-header ad-wizard-head"><div><h4 class="modal-title">Add staff member</h4><p>Start with the essentials. You can complete optional details later.</p></div><div class="ad-head-actions"><span class="ad-time">About 2 minutes</span><button type="button" class="close ad-wizard-close" data-dismiss="modal" aria-label="Close">×</button></div></header>
 <main class="modal-body ad-wizard-body"><form id="ad-staff-form" enctype="multipart/form-data" novalidate><div class="ad-wizard-panels">
  <div class="ad-wizard-panel active" data-wizard-panel="0"><section class="ad-wizard-section"><h4>Profile</h4><div class="ad-profile"><div class="ad-photo-box"><div class="ad-photo-preview" id="ad-photo-preview">No image</div><div class="ad-upload-copy"><label for="ad-staff-photo">Add photo</label><input type="file" name="staff_photo" id="ad-staff-photo" accept="image/*"></div></div><div class="ad-wizard-grid ad-essential"><div class="ad-field"><label>First name <span class="ad-required">*</span></label><input name="staff_name" required placeholder="Enter first name"></div><div class="ad-field"><label>Surname</label><input name="surname" placeholder="Enter surname"></div><div class="ad-field"><label>Phone number <span class="ad-required">*</span></label><input name="staff_phone" required placeholder="e.g. 0712 345 678"></div><div class="ad-field"><label>National ID</label><input name="staff_nid" placeholder="e.g. 1234567890123"></div><div class="ad-field"><label>Email</label><input type="email" name="staff_email" placeholder="name@example.com"></div><div class="ad-field"><label>Residence <span class="ad-required">*</span></label><input name="staff_residence" required placeholder="Select residence"></div></div></div></section><details class="ad-optional"><summary><span class="ad-info">i</span><span class="ad-optional-copy"><strong>Optional information</strong><small>Alias, WhatsApp, address and statutory numbers</small></span><span>⌄</span></summary><div class="ad-optional-fields"><div class="ad-wizard-grid"><div class="ad-field"><label>Alias</label><input name="alias" placeholder="Known as"></div><div class="ad-field"><label>WhatsApp number</label><input name="whatsphone"></div><div class="ad-field"><label>Address</label><input name="staff_address"></div><div class="ad-field"><label>NHIF number</label><input name="staff_nhif"></div><div class="ad-field"><label>NSSF number</label><input name="staff_nssf"></div><div class="ad-field"><label>KRA PIN</label><input name="staff_kra_pin"></div></div></div></details></div>
  <div class="ad-wizard-panel" data-wizard-panel="1"><section class="ad-wizard-section"><h4>Next of kin details</h4><div class="ad-wizard-grid two"><div class="ad-field"><label>Name <span class="ad-required">*</span></label><input name="nok_name" required></div><div class="ad-field"><label>Phone number <span class="ad-required">*</span></label><input name="nok_phone" required></div><div class="ad-field"><label>Relationship <span class="ad-required">*</span></label><select name="nok_relationship" id="ad-nok-relationship" required><option value="">Loading relationships...</option></select></div><div class="ad-field"><label>ID number</label><input name="nok_id"></div><div class="ad-field"><label>Address</label><input name="nok_address"></div><div class="ad-field"><label>Residence</label><input name="nok_residence"></div></div></section></div>
  <div class="ad-wizard-panel" data-wizard-panel="2"><section class="ad-wizard-section"><h4>Employment details</h4><div class="ad-wizard-grid"><div class="ad-field"><label>Department</label><input name="department_name"></div><div class="ad-field"><label>Job title</label><input name="job_title"></div><div class="ad-field"><label>Supervisor</label><input name="supervisor_name"></div><div class="ad-field"><label>Employment type</label><select name="employment_type"><option value="">Select type</option><option>Permanent</option><option>Contract</option><option>Casual</option><option>Intern</option></select></div><div class="ad-field"><label>Contract type</label><select name="contract_type"><option value="">Select contract</option><option>Open ended</option><option>Fixed term</option><option>Part time</option></select></div><div class="ad-field"><label>Work status</label><select name="work_status"><option>Active</option><option>Inactive</option><option>On leave</option></select></div><div class="ad-field"><label>Start date</label><input type="date" name="start_date"></div><div class="ad-field"><label>Hire date</label><input type="date" name="hire_date"></div><div class="ad-field"><label>Probation ends</label><input type="date" name="probation_end_date"></div><div class="ad-field"><label>Contract ends</label><input type="date" name="contract_end_date"></div><div class="ad-field"><label>Salary cycle</label><select name="salary_cycle"><option value="">Select cycle</option><option>Monthly</option><option>Weekly</option><option>Daily</option></select></div><div class="ad-field"><label>Salary type</label><select name="salary_type"><option value="">Select type</option><option>Basic</option><option>Hourly</option><option>Commission</option></select></div><div class="ad-field"><label>Salary amount</label><input type="number" min="0" step="0.01" name="basic_salary" placeholder="0.00"></div><div class="ad-field full"><label>Notes</label><textarea name="employment_notes"></textarea></div></div></section></div>
  <div class="ad-wizard-panel" data-wizard-panel="3"><section class="ad-wizard-section"><h4>Staff documents</h4><div class="ad-wizard-grid two"><label class="ad-document"><span><strong>National ID</strong><small>Front or combined ID document</small></span><input type="file" name="staff_nid_img" accept="image/*,.pdf"></label><label class="ad-document"><span><strong>Curriculum vitae</strong><small>PDF or document file</small></span><input type="file" name="staff_cv" accept=".pdf,.doc,.docx"></label><label class="ad-document"><span><strong>Certificate of conduct</strong><small>Supporting compliance document</small></span><input type="file" name="staff_conduct_img" accept="image/*,.pdf"></label><label class="ad-document"><span><strong>Next of kin ID</strong><small>Identity document for next of kin</small></span><input type="file" name="staff_kin_id_image" accept="image/*,.pdf"></label></div></section></div>
  <div class="ad-wizard-panel" data-wizard-panel="4"><section class="ad-wizard-section"><h4>System access</h4><div class="ad-wizard-section" style="background:#faf7ff"><label><input type="checkbox" name="make_user" value="1" id="ad-make-user"> <strong>Create a system user for this staff member</strong></label></div><div id="ad-user-fields" style="display:none"><div class="ad-wizard-grid two"><div class="ad-field"><label>Username <span class="ad-required">*</span></label><input name="username" id="ad-user-name"></div><div class="ad-field"><label>User role <span class="ad-required">*</span></label><select name="role_id" id="ad-user-role" required><option value="">Loading roles...</option></select></div><div class="ad-field" id="ad-password-field" style="display:none"><label>Password</label><input type="password" name="user_password" id="ad-user-password"></div><div class="ad-field" id="ad-password-confirm-field" style="display:none"><label>Confirm password</label><input type="password" name="user_password_confirm" id="ad-user-password-confirm"></div><div class="ad-field" id="ad-pin-field" style="display:none"><label>PIN</label><input type="password" name="user_pin" id="ad-user-pin"></div><div class="ad-field" id="ad-pin-confirm-field" style="display:none"><label>Confirm PIN</label><input type="password" name="user_pin_confirm" id="ad-user-pin-confirm"></div><div class="ad-field" id="ad-default-role-field" style="display:none"><label>Default role</label><select name="drole"><option value="0">Select default role</option><option value="1">CASHIER</option><option value="2">WAITER</option><option value="3">KITCHEN CASHIER</option></select></div></div></div></section></div>
  <div class="ad-wizard-panel" data-wizard-panel="5"><section class="ad-wizard-section"><h4>Review &amp; save</h4><div class="ad-review" id="ad-wizard-review"><div class="ad-review-card"><h5>Staff details</h5><p>Complete the previous steps to review this profile.</p></div></div></section></div>
 </div><p class="ad-wizard-error" id="ad-wizard-error"></p></form></main>
 <footer class="modal-footer ad-wizard-foot"><span class="ad-required-note">Required fields are marked <span class="ad-required">*</span></span><button type="button" class="back" id="ad-wizard-back">← Back</button><span class="ad-wizard-status" id="ad-wizard-status"><strong>Step 1 of 6</strong> · Basic Details</span><div class="ad-foot-actions"><button type="button" id="ad-save-draft">▣ Save draft</button><button type="button" class="next" id="ad-wizard-next">Continue to Next of Kin →</button><button type="button" class="save" id="ad-wizard-save" style="display:none">✓ Save Staff</button></div></footer>
</div>